const lengthB = 100;

const angle = $state.angle * Math.PI / 180;

const ax = lengthA * Math.cos(0);
const ay = lengthA * Math.sin(0);

const bx = lengthB * Math.cos(angle);
const by = lengthB * Math.sin(angle);

const dotProduct = lengthA * lengthB * Math.cos(angle);

